import * as React from 'react';
import { useNavigate } from 'react-router-dom';
import { CardContent, Grid, IconButton, Tooltip, Fab } from '@mui/material';
// project imports
import MainCard from 'ui-component/cards/MainCard';
import { useSelector } from 'store';
import { getRolesList } from 'store/slices/userList';
// assetss
import EditIcon from '@mui/icons-material/Edit';
import PrintIcon from '@mui/icons-material/PrintTwoTone';
import AddIcon from '@mui/icons-material/AddTwoTone';
import DynamicTable from 'views/commons/tables/DynamicTable';
import DeleteIcon from '@mui/icons-material/Delete';
import DeleteAlert from 'views/commons/alerts/deleteAlarts';
import useSnackbar from 'hooks/useSnackbar';
import { useTheme } from '@mui/material/styles';
import useAuth from 'hooks/useAuth';
import GenericSearchFilter from 'views/commons/search/GenericSearchFilter';
import FilterListIcon from '@mui/icons-material/FilterList';
import { ROLES_SEARCH_FIELDS, ROLES_TABLE_FIELDS } from 'store/constant';
import useTableManagement from 'hooks/useTableManagement';

const RoleListView = () => {
    const { user } = useAuth();
    const theme = useTheme();
    const navigate = useNavigate();
    const { entities } = useSelector((state) => state.usersList);
    const roles = entities.roles || [];

    const [deleteDialogOpen, setDeleteDialogOpen] = React.useState(false);
    const [selectedIds, setSelectedIds] = React.useState([]);
    const { showSnackbar } = useSnackbar();
    const [searchParams, setSearchParams] = React.useState({}); // ✅ Stores search filter params
    const [filterOpen, setFilterOpen] = React.useState(false);
    const {
        rowsPerPage,
        page,
        totalRecords, // ✅ Get total from Redux
        orderBy,
        order,
        handlePageChange,
        handleRowsPerPageChange,
        handleSortChange,
        handleSearch,
        handleFilters,
        handleSelectAll,
        handleRowClick,
        selected,
        setSelected,
        loading,
        fetchData,
        setLoading
    } = useTableManagement({ fetchFunction: getRolesList });

    const handleDelete = (selectedIds) => {
        if (selectedIds.length === 0) return;
        setSelectedIds(selectedIds);
        setDeleteDialogOpen(true);
    };
    return (
        <MainCard content={false} sx={{ background: theme.palette.text.primary }}>
            <CardContent>
                <Grid container justifyContent="space-between" alignItems="right" spacing={2}>
                    <Grid item xs={12} sm={12} sx={{ textAlign: 'right' }}>
                        <Tooltip title="Print">
                            <IconButton size="large">
                                <PrintIcon />
                            </IconButton>
                        </Tooltip>
                        <Tooltip title="Filter">
                            <IconButton size="large" onClick={() => setFilterOpen(!filterOpen)}>
                                <FilterListIcon />
                            </IconButton>
                        </Tooltip>
                        {/* product add & dialog */}
                        <Tooltip title="Add Role">
                            <Fab
                                color="primary"
                                size="small"
                                onClick={() => navigate('/user/role/add')}
                                sx={{ boxShadow: 'none', ml: 1, width: 32, height: 32, minHeight: 32 }}
                            >
                                <AddIcon fontSize="small" />
                            </Fab>
                        </Tooltip>
                    </Grid>
                </Grid>
                <Grid container justifyContent="space-between" alignItems="center" spacing={2}>
                    <Grid item xs={12} sm={12}>
                        <GenericSearchFilter
                            fields={ROLES_SEARCH_FIELDS}
                            onSearch={(values) => {
                                setSearchParams(values); // ✅ Update search state
                                handleFilters(values); // ✅ Trigger API with new search values
                            }}
                            onFilter={handleFilters}
                            searchValues={searchParams} // ✅ Use `searchParams`
                            setSearchValues={setSearchParams} // ✅ Use `setSearchParams`
                            searchMode="manual"
                            expanded={filterOpen}
                            setExpanded={setFilterOpen}
                            loading={loading}
                        />
                    </Grid>
                </Grid>
            </CardContent>
            <DynamicTable
                columns={ROLES_TABLE_FIELDS}
                data={roles}
                total={totalRecords}
                page={page}
                rowsPerPage={rowsPerPage}
                onPageChange={handlePageChange}
                onRowsPerPageChange={handleRowsPerPageChange}
                order={order}
                orderBy={orderBy}
                onRequestSort={handleSortChange}
                selected={selected || []}
                onSelectAllClick={handleSelectAll} // ✅ Pass select all function
                onRowClick={handleRowClick} // ✅ Pass row selection function
                onDelete={handleDelete} // ✅ Pass delete function
                showCheckbox // ✅ Add this to show checkboxes
                renderActions={(row) => (
                    <>
                        <IconButton size="small" onClick={() => navigate(`/user/role/edit/${row.id}`)}>
                            <EditIcon />
                        </IconButton>
                        <IconButton disabled={selected.length > 0} size="small" onClick={() => handleDelete([row.id])}>
                            <DeleteIcon />
                        </IconButton>
                    </>
                )}
                loading={loading}
                customize={theme.palette.mode === 'dark'}
                customtheme="light"
            />

            <DeleteAlert
                open={deleteDialogOpen}
                onClose={() => setDeleteDialogOpen(false)}
                selectedIds={selectedIds}
                endpoint="/users/delete-roles"
                onDeleteSuccess={() => {
                    showSnackbar('Role deleted successfully!', 'success');
                    fetchData({}, () => {
                        setDeleteDialogOpen(false);
                        setSelected([]);
                        setSelectedIds([]); // ✅ Clear selection after delete
                    });
                }}
                message="Are you sure you want to delete the selected roles?"
            />
        </MainCard>
    );
};

export default RoleListView;
